-- GENERATED by `wfj generate` from data/spell/spell-0410.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("spell", {
  [410010] = { "脚部にHand of Sacrificeのルーンを刻みます：\n\n$I1\n対象のパーティーまたはレイドのメンバーが受けたダメージの$N1%を術者に移します。$D1の間、または術者が最大体力の$N3%を移し終えるまで持続します。", nil, 0xdaa134e6, nil, "um" },
  [410011] = { "脚部にInspiration Exemplarのルーンを刻みます：\n\n$I1\n自分の鼓舞する存在が、近くのパーティーメンバーのFearとSleep効果を定期的に解除します。", nil, 0xe2484e74, nil, "um" },
  [410013] = { "腕甲にHammer of the Righteousのルーンを刻みます：\n\n$I1\n現在の対象と近くの対象最大$N1体を槌で打ち、それぞれにメインハンド武器の秒間ダメージの$N2倍に等しいHolyダメージを与えます。Crusader Strikeとクールダウンを共有します。", nil, 0x827a4325, nil, "um" },
  [410014] = { "胸部にDivine Stormのルーンを刻みます：\n\n$I1\n即時の武器攻撃で、$N3ヤード以内の敵最大$N2体に武器ダメージの$N1%を与えます。Divine Stormは、パーティーまたはレイドのメンバー最大3人を、与えたダメージの合計$N5%分回復します。", nil, 0xc83fa68f, nil, "um" },
  [410015] = { "外套にDivine Lightのルーンを刻みます：\n\n$I1\n味方の対象を$N1回復します。対象への過剰な治療の$N2%は、$D1持続する吸収シールドに変換されます。Divine Lightを複数回詠唱しても、このシールドは累積しません。\n\nDivine Lightは、Holy Lightによって発動する、またはHoly Lightを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0xf2c34b96, nil, "um" },
  [410021] = { "胸部か法衣にWild Strikesのルーンを刻みます：\n\n$I1\nCat Form、Bear Form、Dire Bear Formの間、$N1ヤード以内のパーティーまたはレイドのメンバーの戦闘の猛々しさが増します。近接攻撃が命中するたびに$N2%の確率で、攻撃者に$N3%の追加Attack Powerを伴う追加攻撃を与えます。対象がすでにWindfury Totemの恩恵を受けている場合は効果がありません。", nil, 0x279a79a2, nil, "um" },
  [410023] = { { "脚部にSavage Roarのルーンを刻みます：\n\n$I1\n|CFFFFFFFF必要：Cat Form|R\nCat Formの間、与えるPhysicalダメージを$N1%増加させるフィニッシュ技です。コンボポイントが多いほど効果時間が長くなります：\n 1ポイント：$N3秒\n 2ポイント：$N5秒\n 3ポイント：$N7秒\n 4ポイント：$N9秒\n 5ポイント：$N11秒", "脚部にSavage Roarのルーンを刻みます：\n\n$I1\n|CFFFF2020必要：Cat Form|R\nCat Formの間、与えるPhysicalダメージを$N1%増加させるフィニッシュ技です。コンボポイントが多いほど効果時間が長くなります：\n 1ポイント：$N3秒\n 2ポイント：$N5秒\n 3ポイント：$N7秒\n 4ポイント：$N9秒\n 5ポイント：$N11秒", shape = { "11/0", "11/0" } }, nil, 0x292d7b71, nil, "um" },
  [410025] = { "手袋にMangleのルーンを刻みます：\n\n$I1\n対象に噛みつき、通常ダメージの$N1%に加えて$N2を与えます。", nil, 0x07e7bc10, nil, "um" },
  [410027] = { "ブーツにSurvival Instinctsのルーンを刻みます：\n\n$I1\n発動すると、最大体力の$N1%を得て、$D1の間、与えるPhysical以外のすべての治療が$N2%増加します。効果が切れると、その体力は失われます。Moonkin Form以外のすべてのフォームで使用できます。\n\nさらに、Bear FormかDire Bear Formの間は回避するたびに怒りを$N4、Cat Formの間はエネルギーを$N5、その他のフォームの間は最大マナの$N6%を回復します。", nil, 0xb1a4b583, nil, "um" },
  [410028] = { "手袋にWild Growthのルーンを刻みます：\n\n$I1\n対象とそのパーティーを$D1かけて$N1回復します。パーティーメンバーは対象から$N3ヤード以内にいる必要があります。回復量は最初は多く、Wild Growthが効果時間の終わりに近づくにつれて少なくなります。", nil, 0xf3ff628e, nil, "um" },
  [410029] = { "ベルトにEclipseのルーンを刻みます：\n\n$I1\nWrathが、次の$N1回のStarfireの詠唱時間を$D1短縮します。チャージは最大$N3回まで蓄えられます。$D2持続します。", nil, 0xf6c8a77f, nil, "um" },
  [410033] = { "脚部にLifebloomのルーンを刻みます：\n\nRejuvenationとLifebloomのグローバルクールダウンを$D1短縮し、Lifebloomのアビリティを得ます：\n\n$I1\n対象を$D2かけて$N2回復します。Lifebloomが効果時間を終えるか解除されると、対象は即座に$N4回復し、ドルイドは呪文のコストの半分を取り戻します。この効果は同じ対象に最大$N5回まで累積します。", nil, 0xcebd1350, nil, "um" },
  [410059] = { "ベルトにNourishのルーンを刻みます：\n\n$I1\n味方の対象を$N1回復します。対象にRejuvenation、Regrowth、Lifebloom、Wild Growthのいずれかの効果がある場合、さらに20%多く回復します。この呪文は、Healing TouchまたはRegrowthに関連するすべての効果の恩恵を受け、それらを発動させます。", nil, 0x4c436437, nil, "um" },
  [410060] = { "ブーツにDreamstateのルーンを刻みます：\n\n$I1\nダメージを与える非周期の呪文がクリティカルになると、$D1の間、詠唱中もマナ回復の$N1%が継続します。", nil, 0xddd238a5, nil, "um" },
  [410061] = { "胸部か法衣にFury of Stormrageのルーンを刻みます：\n\n$I1\nWrathのマナ消費を$N1%減らし、Wrathでダメージを与えるたびに$N2%の確率で、$D1以内に次に詠唱するHealing Touchが即時詠唱になり、どのシェイプシフトフォームでも詠唱できるようになります。Tree of Lifeフォームの間もWrathを詠唱できます。", nil, 0xec987f0e, nil, "um" },
  [410093] = { "ベルトにFire Novaのルーンを刻みます：\n\n$I1\nFire Nova TotemがFire Novaに置き換わります。Fire Novaは現在のFireトーテムの位置からダメージを放出させます。", nil, 0x579f11e5, nil, "um" },
  [410094] = { "胸部か法衣にOverloadのルーンを刻みます：\n\n$I1\nLightning BoltとChain Lightningに、$N1%の確率で同じ対象に同様の呪文を追加コストなしでもう一度詠唱する効果が付きます。この呪文のダメージは半分で、脅威は発生しません。", nil, 0xaaca0719, nil, "um" },
  [410095] = { "手袋にLava Burstのルーンを刻みます：\n\n$I1\n対象に溶岩を投げつけ、$N1のFireダメージを与えます。対象にFlame Shockがかかっている場合、Lava Burstのダメージが$N2%増加します。", nil, 0x5526c59e, nil, "um" },
  [410096] = { "胸部か法衣にDual Wield Specializationのルーンを刻みます：\n\n$I1\n二刀流の間、呪文と近接攻撃の両方の命中率が$N1%上昇し、Stormstrikeが両方の武器で命中するようになり、オフハンド武器のダメージが$N2%増加します。", nil, 0x74d5756d, nil, "um" },
  [410097] = { "手袋にWater Shieldのルーンを刻みます：\n\n$I1\n術者を$N1個の水の球が取り囲みます。呪文、近接攻撃、遠隔攻撃が術者に命中したとき、または術者の治療呪文がクリティカルになったとき、最大マナの$N2%が術者に回復し、水の球を一つ消費します。球は数秒に一度しか発動しません。$D1持続します。\n\nシャーマンに同時にかけられるElemental Shieldは一つだけです。", nil, 0xba523d1e, nil, "um" },
  [410098] = { "胸部か法衣にShield Masteryのルーンを刻みます：\n\n$I1\nBlockするたびに、最大マナの$N1%に等しいマナを回復し、盾のアーマー値の$N2%に等しいアーマーを得ます。最大$N3回まで累積します。また、Block率が常に$N4%上昇し、Block値が$N5%増加します。\n\nさらに、Shockのアビリティを使うたびに、Defenseスキルが$N7を超えるポイントごとにSpell Damageを$N6得ます。$D1持続します。", nil, 0xfc4a3b79, nil, "um" },
  [410099] = { "脚部にAncestral Guidanceのルーンを刻みます：\n\n$I1\n次の$D1の間、与えたダメージの$N2%が近くのパーティーメンバー最大3人への治療に変換され、与えた治療の$N4%が最新のFlame Shockの対象へのダメージに変換されます。", nil, 0x00771271, nil, "um" },
  [410100] = { "ベルトにMaelstrom Weaponのルーンを刻みます：\n\n$I1\n近接攻撃でダメージを与えると、一定の確率で次のLightning Boltの詠唱時間とマナ消費を$N1%減らします。最大$N2回まで累積します。$D1持続します。", nil, 0x127a4c8a, nil, "um" },
  [410101] = { "脚部にEarth Shieldのルーンを刻みます：\n\n$I1\n大地の盾で対象を守り、ダメージを受けたときに失う詠唱またはチャネリングの時間を$N1%減らし、攻撃を受けると盾をまとった対象を$N2回復させます。この効果は数秒に一度しか発生しません。チャージ$N3回。$D1持続します。Earth Shieldは同時に一体の対象にしかかけられません。", nil, 0x639cc53d, nil, "um" },
  [410103] = { "ブーツにSpirit of the Alphaのルーンを刻みます：\n\n$I1\n対象にアルファ狼の魂を宿らせ、$D1の間、対象が発生させるすべての脅威を$N1%増加させます。対象は1体まで。自分以外にかけた場合、シャーマンもLoyal Betaを得て、$D2の間、与えるPhysicalダメージが$N4%増加し、発生させるすべての脅威が$N5%減少します。Spirit of the AlphaとLoyal Betaを同時に得ることはできません。", nil, 0x1e19e35c, nil, "um" },
  [410104] = { "手袋にLava Lashのルーンを刻みます：\n\n$I1\nオフハンド武器に溶岩をまとわせ、即座にオフハンドのWeaponダメージの$N1%を与えます。オフハンド武器にFlametongueのエンチャントがかかっている場合、ダメージが$N2%増加します。", nil, 0x98cf6597, nil, "um" },
  [410105] = { "腕甲にRiptideのルーンを刻みます：\n\n$I1\n味方の対象を$N1回復し、さらに$D1かけて$N2回復します。また、その対象に直接詠唱するChain Healの効果が$N4%上昇します。", nil, 0xa6711e36, nil, "um" },
  [410107] = { "脚部にWay of Earthのルーンを刻みます：\n\n$I1\nメインハンド武器にRockbiter Weaponが有効で、盾を装備している間、発生させる脅威が$N1%増加し、体力が$N2%増加し、受けるダメージが$N3%減少し、近接攻撃でクリティカルヒットを受ける確率が$N4%減少し、Earth Shockが対象を挑発して自分を攻撃させるようになり、他のShock呪文とは別のクールダウンを持ちますが、射程は近接の範囲に短縮されます。ただし、Lightning Bolt、Chain Lightning、Chain Heal、Healing Wave、Lava Burstの射程は$N5ヤード短縮されます。", nil, 0xc958e370, nil, "um" },
  [410109] = { "ベルトにSteady Shotのルーンを刻みます：\n\n$I1\n遠隔武器ダメージの$N1%を与える、狙いすました射撃です。", nil, 0x78ab7381, nil, "um" },
  [410110] = { "胸部か法衣にBeast Masteryのルーンを刻みます：\n\n$I1\nペットのダメージと体力が$N1%増加し、Focusの回復が$N2%増加します。さらに、ペットのGrowlが$D1の間、対象をTauntしてペットを攻撃させるようにもなります。", nil, 0xb471819e, nil, "um" },
  [410111] = { "脚部にKill Shotのルーンを刻みます：\n\n$I1\n傷ついた対象へのとどめを試み、$N1%の武器ダメージに加えて$N2を与える遠隔攻撃を放ちます。Kill Shotには最小射程がありません。体力が20%以下の敵に使用すると、Kill Shotのクールダウンがリセットされます。", nil, 0x54750420, nil, "um" },
  [410113] = { "胸部か法衣にMaster Marksmanのルーンを刻みます：\n\n$I1\nクリティカル率が$N1%上昇し、すべてのShotのアビリティのマナ消費が$N2%減少します。", nil, 0x05d24437, nil, "um" },
  [410114] = { "ベルトにExpose Weaknessのルーンを刻みます：\n\n$I1\n近接攻撃と遠隔攻撃のクリティカルで、$D1の間、現在の敏捷性の$N1%分だけ攻撃力が上昇します。", nil, 0x79930c44, nil, "um" },
  [410115] = { "手袋にCobra Slayerのルーンを刻みます：\n\n$I1\nMongoose Biteが、近接攻撃のたびに$N1%の確率で発動可能になります。敵が回避した場合は100%です。この確率は累積し、リセットされなければ以後の攻撃ごとに$N3%ずつ上昇します。また、Mongoose BiteはAttack Powerの$N4%に等しい追加ダメージを与えます。", nil, 0xff8b8fc8, nil, "um" },
  [410116] = { "ブーツにDual Wield Specializationのルーンを刻みます：\n\n$I1\nオフハンド武器のダメージが$N1%増加し、二刀流の間、Raptor Strikeが両方の武器で攻撃するようになります。", nil, 0x977a0a79, nil, "um" },
  [410121] = { "手袋にChimera Shotのルーンを刻みます：\n\n$I1\n$N1%の武器ダメージを与え、対象にかかっている現在のStingを更新し、効果を発動させます：\n\nSerpent Sting - Serpent Stingが与えたダメージの$N2%を即座に与えます。\n\nViper Sting - Viper Stingが吸収した総量の$N3%に等しいマナを即座に回復します。\n\nScorpid Sting - $D1の間、対象をDisarmしようと試みます。この効果は1分に一度しか発生しません。", nil, 0x58d16ab2, nil, "um" },
  [410122] = { "胸部か法衣にLone Wolfのルーンを刻みます：\n\n$I1\nペットを出していない間、すべての攻撃のダメージが$N1%増加します。", nil, 0x1ee57669, nil, "um" },
  [410176] = { "$N1ヤード以内の対象に突進して頭蓋を打ち据え、呪文の詠唱を中断させ、$D1の間その系統の呪文を唱えられなくします。Feral Chargeとクールダウンを共有します。", nil, 0xf9555e00, nil, "um" },
  [410412] = { "対象を挑発して自分を攻撃させます。ただし、対象がすでに自分を攻撃している場合は効果がありません。", nil, 0x71de38fd, nil, "um" },
  [410958] = { "Memoryに意識を集中させ、新しい呪文を習得します。Azerothの霊的な神秘について瞑想し、澄みきった心が必要です。", nil, 0x71e0620a, nil, "um" },
  [410971] = { "Prophecyに意識を集中させ、新しい呪文を習得します。Azerothの二つの霊的な神秘について瞑想し、研ぎ澄まされた心が必要です。", nil, 0xe0dfb45b, nil, "um" },
})
